/**
 * @vitest-environment node
 *
 * GREEN TEST — issue #1897, proof 2 of 2.
 *
 * ## Context
 *
 * Issue #1897: the blanket *.g.cs exclusion pattern hid ALL .g.cs files,
 * even those that are hand-maintained and contain real duplication. Only
 * ResponseKeys.g.cs (auto-generated by PublyApp.Scripts) should be excluded.
 *
 * The fix: GENERATED_FILE_PATHS is an explicit Set containing only
 * ResponseKeys.g.cs. Arbitrary .g.cs files are no longer excluded.
 *
 * ## What the proof asserts (green direction)
 *
 * The proof asserts the CORRECT outcome: only ResponseKeys.g.cs is excluded;
 * arbitrary .g.cs files are NOT excluded.
 *
 * ## Replay
 *   cd packages/scripts-ts && pnpm exec vitest run --config vitest.preuves.config.ts \
 *     tests/proofs/1897/green-1897-targeted-gcs-exclusion.test.ts
 *
 * Expected: PASS — only the explicit generated file is excluded.
 */
import assert from 'node:assert/strict';

import { test } from 'vitest';

import { isSpecFile } from '../../../src/check-jscpd.ts';

test('GREEN: with targeted exclusion, only explicit generated files are excluded', () => {
	// The one known generated file — must be excluded.
	const generatedFile = 'apps/api/Localization/ResponseKeys.g.cs';
	assert.strictEqual(
		isSpecFile(generatedFile),
		true,
		'GREEN proof: ResponseKeys.g.cs is generated and must be excluded',
	);

	// An arbitrary .g.cs file — must NOT be excluded.
	const nonGeneratedGcs = 'apps/api/Modules/Foo/SomeCustom.g.cs';
	assert.strictEqual(
		isSpecFile(nonGeneratedGcs),
		false,
		'GREEN proof: non-generated .g.cs files count as production',
	);
});
